func (r *mutationResolver) CreateFuelPurchaseImport(ctx context.Context, input gqlmodel.CreateFuelPurchaseImportInput) (*fuelpurchase.ImportBatch, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceFuelPurchase, permission.OpImport)
	if err != nil {
		return nil, err
	}

	cardID, err := optionalScopedID("defaultFuelCardId", input.DefaultFuelCardID)
	if err != nil {
		return nil, err
	}

	mapping, err := fuelImportMappingFromGraphQL(input.Mapping)
	if err != nil {
		return nil, err
	}

	req := &fuelpurchaseservice.CreateImportRequest{
		TenantInfo:        tenantInfo(authCtx),
		Provider:          input.Provider,
		DefaultFuelCardID: cardID,
		DefaultCurrency:   stringValue(input.DefaultCurrency),
		Mapping:           mapping,
		UserID:            authCtx.UserID,
	}
	if input.DefaultFuelType != nil {
		req.DefaultFuelType = *input.DefaultFuelType
	}

	return r.fuelPurchaseService.CreateImport(ctx, req)
}

