func (r *queryResolver) FuelPurchaseImportTemplate(ctx context.Context, provider fuelpurchase.CardProvider) (*gqlmodel.FuelImportTemplate, error) {
	if _, err := r.requirePermission(ctx, permission.ResourceFuelPurchase, permission.OpImport); err != nil {
		return nil, err
	}

	if !provider.IsValid() {
		return nil, errortypes.NewValidationError(
			"provider",
			errortypes.ErrInvalid,
			"Provider is not one Trenova can build a template for",
		)
	}

	fileName, content := r.fuelPurchaseService.Template(provider)

	return &gqlmodel.FuelImportTemplate{FileName: fileName, Content: content}, nil
}

